param([string]$RunRoot,[string]$SavedPath,[ValidateSet('old-open','fresh-open')][string]$Step,[int]$AppId,[long]$Created,[bool]$ForegroundPending,[long]$ForegroundAfter,[int]$ForegroundPid,[long]$ForegroundTime)
$ErrorActionPreference='Stop';Assert-OwnNativeIdentity
$expectedCommand="[Console]::OutputEncoding=[System.Text.UTF8Encoding]::new(); Add-Type -AssemblyName System.Windows.Forms; `$d=[System.Windows.Forms.OpenFileDialog]::new(); `$d.Filter='FBones / Spine project|*.fbones;*.spine'; if(`$d.ShowDialog() -eq 'OK'){[Console]::Write(`$d.FileName)}"
$expectedImage=Join-Path $PSHOME 'powershell.exe';$expectedPowerShellSha=(Get-FileHash -LiteralPath $expectedImage -Algorithm SHA256).Hash.ToLowerInvariant()
if([IO.Path]::GetFullPath($SavedPath) -ne (Join-Path $RunRoot 'projects\own-upgrade.fbones') -or (Get-FileHash -LiteralPath $SavedPath -Algorithm SHA256).Hash.ToLowerInvariant() -ne 'e74a15b08b9cbc85f943ddde46c37c5cbceed3eb70968932ccd416697c6ecb5d'){throw 'Exact own unchanged Open fixture required'}
function DialogJson([string]$Suffix,$Value){$path=Join-Path $RunRoot ('reports\'+$Step+'-'+$Suffix+'.json');$bytes=[Text.Encoding]::UTF8.GetBytes(($Value|ConvertTo-Json -Depth 20));if($bytes.Length -gt 524288){throw 'Dialog receipt byte cap'};$stream=[IO.File]::Open($path,[IO.FileMode]::CreateNew,[IO.FileAccess]::Write,[IO.FileShare]::Read);try{$stream.Write($bytes,0,$bytes.Length)}finally{$stream.Dispose()}}
$process=$null;$dialog=[IntPtr]::Zero;$deadline=[DateTime]::UtcNow.AddSeconds(15)
do{Assert-OwnNativeIdentity;$children=@(Get-CimInstance Win32_Process -Filter ('ParentProcessId='+$AppId)|Where-Object {$_.Name -eq 'powershell.exe'});$found=@(foreach($child in $children){foreach($h in [OwnCoreFileControls]::Tops([uint32]$child.ProcessId)){[pscustomobject]@{Pid=$child.ProcessId;Window=$h;Row=$child}}});if($found.Count -gt 1){throw 'Multiple own native child dialogs'};if($found.Count -eq 1){$process=Get-Process -Id $found[0].Pid;$dialog=[IntPtr]$found[0].Window;$childRow=$found[0].Row;break};Start-Sleep -Milliseconds 100}while([DateTime]::UtcNow -lt $deadline)
if(!$process -or $dialog -eq [IntPtr]::Zero){throw 'No new own native Open dialog'}
$childHandle=$process.Handle;try{
$dialogCreated=[long]0;$childExited=[long]0;$childKernel=[long]0;$childUser=[long]0;if([NativeOwnGui]::WaitForSingleObject($childHandle,0) -ne 258 -or ![NativeOwnGui]::GetProcessTimes($childHandle,[ref]$dialogCreated,[ref]$childExited,[ref]$childKernel,[ref]$childUser) -or $dialogCreated -le 0 -or $process.StartTime.ToUniversalTime().ToFileTimeUtc() -ne $dialogCreated){throw 'New helper retained kernel identity unavailable'};
$command=[OwnCoreFileControls]::Argv([string]$childRow.CommandLine)
if($dialogCreated -lt $Created -or $process.MainModule.FileName -ne $expectedImage -or (Get-FileHash -LiteralPath $process.MainModule.FileName -Algorithm SHA256).Hash.ToLowerInvariant() -ne $expectedPowerShellSha -or $command.Count -ne 5 -or [IO.Path]::GetFileName($command[0]) -ne 'powershell.exe' -or $command[1] -ne '-NoProfile' -or $command[2] -ne '-STA' -or $command[3] -ne '-Command' -or $command[4] -cne $expectedCommand -or [OwnCoreFileControls]::Text($dialog) -ne 'Open'){throw 'Current native PowerShell child/source/creation/purpose mismatch'}
function DialogIdentity{Assert-OwnNativeIdentity;$process.Refresh();$nowCreated=[long]0;$nowExit=[long]0;$nowKernel=[long]0;$nowUser=[long]0;$dialogOwner=[uint32]0;if([NativeOwnGui]::WaitForSingleObject($childHandle,0) -ne 258 -or ![NativeOwnGui]::GetProcessTimes($childHandle,[ref]$nowCreated,[ref]$nowExit,[ref]$nowKernel,[ref]$nowUser) -or $nowCreated -ne $dialogCreated -or [OwnCoreFileControls]::GetWindowThreadProcessId($dialog,[ref]$dialogOwner) -eq 0 -or $dialogOwner -ne $process.Id){throw 'Retained helper PID/start/window owner changed'};$row=Get-CimInstance Win32_Process -Filter ('ProcessId='+$process.Id);if($process.HasExited -or $process.StartTime.ToUniversalTime().ToFileTimeUtc() -ne $dialogCreated -or $row.ParentProcessId -ne $AppId -or $process.MainModule.FileName -ne $expectedImage -or [OwnCoreFileControls]::Text($dialog) -ne 'Open'){throw 'Own Open child identity changed'}}
function UiaControl([IntPtr]$Handle){try{$e=[Windows.Automation.AutomationElement]::FromHandle($Handle);$c=$e.Current;$pattern=$null;$has=$e.TryGetCurrentPattern([Windows.Automation.ValuePattern]::Pattern,[ref]$pattern);return [ordered]@{Name=$c.Name;AutomationId=$c.AutomationId;ControlType=$c.ControlType.ProgrammaticName;ValuePatternAvailable=$has;Value=if($has){$pattern.Current.Value}else{$null}}}catch{return [ordered]@{Error=$_.Exception.Message}}}
function Control([long]$Value){$h=[IntPtr]$Value;$pidValue=[uint32]0;[void][OwnCoreFileControls]::GetWindowThreadProcessId($h,[ref]$pidValue);if($pidValue -ne $process.Id){throw 'Foreign native Open control'};$chain=@();$parent=[OwnCoreFileControls]::GetParent($h);for($d=0;$d -lt 6 -and $parent -ne [IntPtr]::Zero;$d++){$chain+=@([ordered]@{Handle=$parent.ToInt64();Class=[OwnCoreFileControls]::Class($parent);Id=[OwnCoreFileControls]::GetDlgCtrlID($parent)});if($parent -eq $dialog){break};$parent=[OwnCoreFileControls]::GetParent($parent)};return [ordered]@{Handle=$Value;Class=[OwnCoreFileControls]::Class($h);Id=[OwnCoreFileControls]::GetDlgCtrlID($h);Text=[OwnCoreFileControls]::Text($h);Visible=[OwnCoreFileControls]::IsWindowVisible($h);Enabled=[OwnCoreFileControls]::IsWindowEnabled($h);UIA=(UiaControl $h);Ancestors=$chain}}
$ready=$false;$deadline=[DateTime]::UtcNow.AddSeconds(10)
for($attempt=1;$attempt -le 10 -and [DateTime]::UtcNow -lt $deadline;$attempt++){
 DialogIdentity;$handles=[OwnCoreFileControls]::Children($dialog);if($handles.Count -gt 256){throw 'Native Open control count cap'};$controls=@(foreach($h in $handles){Control $h});DialogJson ('inventory-'+$attempt.ToString('00')) ([ordered]@{AppPid=$AppId;AppCreated=$Created;ChildPid=$process.Id;ChildCreated=$dialogCreated;ChildImage=$expectedImage;ChildSha256=$expectedPowerShellSha;Command=$command;Dialog=$dialog.ToInt64();InputOperations=0;Controls=$controls})
 $labels=@($controls|Where-Object {$_.Class -eq 'Static' -and $_.Id -eq 1090 -and $_.Visible -and $_.Enabled -and ($_.Text -replace '&','') -eq 'File name:' -and $_.Ancestors.Count -eq 1 -and $_.Ancestors[0].Handle -eq $dialog.ToInt64()});$edits=@($controls|Where-Object {$_.Class -eq 'Edit' -and $_.Id -eq 1148 -and $_.Visible -and $_.Enabled -and $_.Ancestors.Count -eq 3 -and $_.Ancestors[0].Class -eq 'ComboBox' -and $_.Ancestors[0].Id -eq 1148 -and $_.Ancestors[1].Class -eq 'ComboBoxEx32' -and $_.Ancestors[1].Id -eq 1148 -and $_.Ancestors[2].Handle -eq $dialog.ToInt64()});$buttons=@($controls|Where-Object {$_.Class -eq 'Button' -and $_.Id -eq 1 -and $_.Visible -and $_.Enabled -and ($_.Text -replace '&','') -eq 'Open' -and $_.Ancestors[-1].Handle -eq $dialog.ToInt64()})
 if($labels.Count -eq 1 -and $edits.Count -eq 1 -and $buttons.Count -eq 1){$ready=$true;break};Start-Sleep -Milliseconds 250
}
if(!$ready){throw 'Observed classic Open filename/acceptance chain unqualified; retained inventory/no fallback'}
if($ForegroundPending){$associated=$ForegroundPid -eq $process.Id -and $ForegroundAfter -eq $dialog.ToInt64() -and $dialogCreated -le $ForegroundTime;DialogJson 'foreground-association' ([ordered]@{pending=$true;foregroundHwnd=$ForegroundAfter;foregroundPid=$ForegroundPid;foregroundFileTime=$ForegroundTime;childPid=$process.Id;childCreated=$dialogCreated;dialog=$dialog.ToInt64();passed=$associated});if(!$associated){throw 'Natural Open foreground transition lacks exact current child/dialog association; no filename input'}}
$edit=$edits[0];$button=$buttons[0];DialogIdentity;DialogJson 'filename-intent' ([ordered]@{MaximumSets=1;Path=$SavedPath;Edit=$edit;ChildPid=$process.Id;ChildCreated=$dialogCreated});[OwnCoreFileControls]::SetText([IntPtr]$edit.Handle,$SavedPath);$after=Control $edit.Handle;$uiaText=if($after.UIA.ValuePatternAvailable){$after.UIA.Value}else{$after.UIA.Name};DialogJson 'filename-after' ([ordered]@{RequestedPath=$SavedPath;Control=$after;NativeReadbackExact=($after.Text -ceq $SavedPath);UIAReadbackExact=($uiaText -ceq $SavedPath)})
if($after.UIA.Error -or $after.Text -cne $SavedPath -or $uiaText -cne $SavedPath){throw 'Native/UIA exact filename readback failed'}
DialogIdentity;$nowButton=Control $button.Handle;if(!$nowButton.Visible -or !$nowButton.Enabled -or $nowButton.Id -ne 1 -or ($nowButton.Text -replace '&','') -ne 'Open' -or $nowButton.Ancestors[-1].Handle -ne $dialog.ToInt64()){throw 'Current native accept changed'};DialogJson 'accept-intent' ([ordered]@{MaximumPosts=1;Path=$SavedPath;ChildPid=$process.Id;ChildCreated=$dialogCreated;Dialog=$dialog.ToInt64();Edit=$after;Accept=$nowButton});$sent=[OwnCoreFileControls]::PostMessage([IntPtr]$button.Handle,245,[IntPtr]::Zero,[IntPtr]::Zero);DialogJson 'accept-result' ([ordered]@{Attempted=$true;Returned=$sent;OnePost=$true});if(!$sent){throw 'Native Open acceptance failed/no retry'}

if([NativeOwnGui]::WaitForSingleObject($childHandle,15000) -ne 0){throw 'Own native Open helper terminal deadline/no force'};$helperCode=[uint32]0;if(![NativeOwnGui]::GetExitCodeProcess($childHandle,[ref]$helperCode) -or $helperCode -ne 0){throw 'Own Open helper did not exit normally0'};DialogJson 'helper-terminal' ([ordered]@{pid=$process.Id;created=$dialogCreated;retainedHandle=$true;normal0=$true;exitCode=$helperCode;noForce=$true})
}finally{$process.Dispose()}
